import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createLogger } from './logger.js';

const skip = createLogger.toString().includes('TODO')
  ? 'exercise not started — remove the TODO marker to activate checks'
  : false;

const fixedClock = () => new Date('2026-06-01T12:30:00.000Z');

test('info emits one queryable event with deterministic time', { skip }, () => {
  const events = [];
  const logger = createLogger({ sink: (event) => events.push(event), clock: fixedClock });
  logger.info('board loaded', { boardId: 7, durationMs: 18 });

  assert.deepEqual(events, [{
    timestamp: '2026-06-01T12:30:00.000Z',
    level: 'info',
    message: 'board loaded',
    boardId: 7,
    durationMs: 18,
  }]);
});

test('base, child, and call context compose without mutation', { skip }, () => {
  const events = [];
  const baseContext = { service: 'api', environment: 'test' };
  const requestContext = { requestId: 'req-42' };
  const logger = createLogger({ sink: (event) => events.push(event), clock: fixedClock, baseContext });
  const requestLogger = logger.child(requestContext);

  requestLogger.warn('slow query', { durationMs: 950 });
  logger.info('still alive');

  assert.equal(events[0].service, 'api');
  assert.equal(events[0].requestId, 'req-42');
  assert.equal(events[0].durationMs, 950);
  assert.equal('requestId' in events[1], false, 'child context must not leak to its parent');
  assert.deepEqual(baseContext, { service: 'api', environment: 'test' });
  assert.deepEqual(requestContext, { requestId: 'req-42' });
});

test('reserved event fields cannot be forged by context', { skip }, () => {
  const events = [];
  const logger = createLogger({ sink: (event) => events.push(event), clock: fixedClock });
  logger.info('real message', {
    timestamp: 'yesterday',
    level: 'admin',
    message: 'forged message',
  });

  assert.equal(events[0].timestamp, '2026-06-01T12:30:00.000Z');
  assert.equal(events[0].level, 'info');
  assert.equal(events[0].message, 'real message');
});

test('sensitive keys are recursively and case-insensitively redacted', { skip }, () => {
  const events = [];
  const logger = createLogger({ sink: (event) => events.push(event), clock: fixedClock });
  logger.info('login attempt', {
    username: 'ana',
    password: 'never-log-me',
    request: {
      headers: { Authorization: 'Bearer abc', cookie: 'session=xyz' },
      body: { nested: { API_TOKEN: 'also-secret', harmless: 'visible' } },
    },
  });

  const text = JSON.stringify(events[0]);
  for (const secret of ['never-log-me', 'Bearer abc', 'session=xyz', 'also-secret']) {
    assert.equal(text.includes(secret), false);
  }
  assert.equal(events[0].request.body.nested.harmless, 'visible');
  assert.equal(events[0].password, '[REDACTED]');
  assert.equal(events[0].request.headers.Authorization, '[REDACTED]');
  assert.equal(events[0].request.body.nested.API_TOKEN, '[REDACTED]');
});

test('errors retain diagnostic identity and context', { skip }, () => {
  const events = [];
  const logger = createLogger({ sink: (event) => events.push(event), clock: fixedClock });
  const error = new TypeError('column is missing');
  logger.error('move failed', error, { cardId: 9 });

  assert.equal(events[0].level, 'error');
  assert.equal(events[0].error.name, 'TypeError');
  assert.equal(events[0].error.message, 'column is missing');
  assert.equal(typeof events[0].error.stack, 'string');
  assert.equal(events[0].cardId, 9);
});

test('undefined fields disappear while null remains meaningful', { skip }, () => {
  const events = [];
  const logger = createLogger({ sink: (event) => events.push(event), clock: fixedClock });
  logger.info('optional values', { absent: undefined, intentionallyEmpty: null });

  assert.equal('absent' in events[0], false);
  assert.equal(events[0].intentionallyEmpty, null);
});

test('caller-owned nested data is never rewritten during redaction', { skip }, () => {
  const events = [];
  const context = { account: { password: 'original', roles: ['user'] } };
  const logger = createLogger({ sink: (event) => events.push(event), clock: fixedClock });
  logger.info('account observed', context);

  assert.deepEqual(context, { account: { password: 'original', roles: ['user'] } });
  assert.equal(events[0].account.password, '[REDACTED]');
});

const DEFAULT_REDACT_KEYS = [
  'password',
  'token',
  'authorization',
  'secret',
  'cookie',
];

/**
 * @param {{
 *   sink?: (event: Record<string, unknown>) => void,
 *   clock?: () => Date,
 *   baseContext?: Record<string, unknown>,
 *   redactKeys?: string[]
 * }} options
 */
export function createLogger({
  sink = (event) => console.log(JSON.stringify(event)),
  clock = () => new Date(),
  baseContext = {},
  redactKeys = DEFAULT_REDACT_KEYS,
} = {}) {
  // TODO: implement the contract in README.md, then delete this marker.
  void sink;
  void clock;
  void baseContext;
  void redactKeys;
  throw new Error('Not implemented');
}
